// Wand sculpture
// texture working on box() (when ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))), but noz on begin/endShape()

let woodTxt,
  boxes = [];

function preload() {
  woodTxt = loadImage(
    "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/16_wood_samples.jpg/832px-16_wood_samples.jpg"
  );
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  describe("grid of wooden boxes in 3D space with same size but different heights of two colors: natural and dark. top natural fading to dark in the bottom");
  createScene();
  noStroke();
}

function draw() {
  background(0, 0, 12);
  orbitControl();
  // lights();
	ambientLight((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width*255);
	pointLight(32,32,32, 0,0,height*1.5);
	spotLight(color("azure"), 0,0,height*1.5, 0,0,-height*0.5)

  for (let b of boxes) {
    b.show();
  }
}

function createScene() {
  const BOX_S = 50,
    TXT_GRID_S = 4,
    GRID_W = 10,
    GRID_H = ~~((GRID_W / 3) * 5);

  let tw, // tile width
    th, // tile height
    ts, // tile size
    txts = [];

  tw = ~~(woodTxt.width / TXT_GRID_S);
  th = ~~(woodTxt.height / TXT_GRID_S);
  ts = min(tw, th);
  // console.log(tw, th, ts);

  for (let y = 0; y < woodTxt.height; y += th) {
    for (let x = 0; x < woodTxt.width; x += tw) {
      // txts.push(txt.get(x, y, ts, ts));
      txts.push(woodTxt.get(x, y, tw, th));
    }
  }

  tintColors = [null, "rgb(91,58,31)"];
  for (let y = 0; y < GRID_H; y++) {
    for (let x = 0; x < GRID_W; x++) {
      const xp = (x - GRID_W / 2) * BOX_S;
      const yp = (y - GRID_H / 2) * BOX_S;
      const f = y / (GRID_H - 1);
      const ti = f + random(-0.4, 0.4) < 0.5 ? 0 : 1;
      boxes.push(
        new Shape(
          { x: xp, y: yp, z: 0 },
          BOX_S,
          random(0.3, 0.8),
          random(txts),
          tintColors[ti]
        )
      );
    }
  }
}

// ----------------------------------------------

class Shape {
  constructor(pos, sze, scl, txt, tnt = null) {
    this.pos = pos;
    this.sze = sze;
    this.scl = map(scl, 0, 1, -1, 1);
    this.rot = ~~random(4) * HALF_PI;
    this.txt = txt; // texture
    this.tnt = tnt; // tint
  }

  show() {
    push();
    // translate(this.pos.x, this.pos.y, this.pos.z + this.sze.z / 2);
    translate(this.pos.x, this.pos.y, this.pos.z);
    rotateZ(this.rot);
		textureMode(NORMAL);
    texture(this.txt);
    if (this.tnt) tint(this.tnt);

    if (false && ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
      box(this.sze);
    } else {
      const s = this.sze / 2;
      var f = this.f;
      const vFTL = [-1, 1, f, 0, 0]; // Front-top-left
      const vFTR = [1, 1, f, 0, 1]; // Front-top-right
      const vFBL = [-1, -1, 1, 1, 0]; // Front-bottom-left
      const vFBR = [1, -1, 1, 1, 1]; // Front-bottom-right
      const vBBR = [1, -1, -1, 0, 0]; // Back-bottom-right
      const vBTR = [1, 1, -1, 0, 1]; // Back-top-right
      const vBTL = [-1, 1, -1, 1, 0]; // Back-top-left
      const vBBL = [-1, -1, -1, 1, 1]; // Back-bottom-left
      const vtcs = [
        vFTL, // Front-top-left
        vFTR, // Front-top-right
        vFBL, // Front-bottom-left
        vFBR, // Front-bottom-right
        vBBR, // Back-bottom-right
        vFTR, // Front-top-right
        vBTR, // Back-top-right
        vFTL, // Front-top-left
        vBTL, // Back-top-left
        vFBL, // Front-bottom-left
        vBBL, // Back-bottom-left
        vBBR, // Back-bottom-right
        vBTL, // Back-top-left
        vBTR, // Back-top-right
      ];

			beginShape(TRIANGLE_STRIP);
      for (let v of vtcs) {
        vertex(s * v[0], s * v[1], s * v[2], v[3], v[4]);
      }
      endShape(); // CLOSE
    }
    pop();
  }
}
